// Reference vectors for the K-quant quantizers: byte output of `ggml_quantize_chunk` from a built
// ggml (llama.cpp commit a3a1c47), for single rows of 512 values taken from the reference tool's
// 48-row data sets, with or without its importance matrix. Produced by the reference library,
// never by this package. Rows were chosen because they are sensitive to which multiply-adds are
// fused (flipping the pattern in `fmaSites` changes their output while the reference bytes stay
// matched), plus an all-block-zero mix (`zeros`). Regenerate with the generator behind the gated
// KQuantOracleTests (TEST_RUNNER_SHEARS_KQUANT_ORACLE).

enum KQuantReferenceVectors {
    struct Entry {
        let kind: String, row: Int, type: String, importance: Bool
        let x: String      // 512 little-endian float32
        let bytes: String  // the reference's output for this row
    }
    /// 512 little-endian float32 per data kind (per column).
    static let imatrices: [String: String] = [
        "lattice": "",
        "normal": "",
        "zeros": "",
    ]
    static let entries: [Entry] = [
        Entry(kind: "heavy", row: 27, type: "q4_k", importance: false,
              x: "",
              bytes: ""),
        Entry(kind: "normal", row: 37, type: "q4_k", importance: true,
              x: "",
              bytes: ""),
        Entry(kind: "positive", row: 2, type: "q5_k", importance: false,
              x: "",
              bytes: ""),
        Entry(kind: "normal", row: 7, type: "q5_k", importance: true,
              x: "",
              bytes: ""),
        Entry(kind: "blockscale", row: 41, type: "q6_k", importance: false,
              x: "",
              bytes: ""),
        Entry(kind: "normal", row: 22, type: "q6_k", importance: true,
              x: "",
              bytes: ""),
        Entry(kind: "lattice", row: 19, type: "q5_0", importance: false,
              x: "",
              bytes: ""),
        Entry(kind: "lattice", row: 19, type: "q5_0", importance: true,
              x: "",
              bytes: ""),
        Entry(kind: "zeros", row: 1, type: "q4_k", importance: false,
              x: "",
              bytes: ""),
        Entry(kind: "zeros", row: 1, type: "q4_k", importance: true,
              x: "",
              bytes: ""),
        Entry(kind: "zeros", row: 1, type: "q6_k", importance: true,
              x: "",
              bytes: ""),
        Entry(kind: "zeros", row: 1, type: "q5_0", importance: true,
              x: "",
              bytes: ""),
    ]
}
